INSERT INTO units (item_type_id, name, order_index) VALUES ('reading', 'C1 - Advanced', 5) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('reading', '{"text": "The committee''s reluctance to commit to a timeline has left stakeholders increasingly skeptical of the initiative''s viability."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('reading', '{"text": "Critics contend that the regulation, however well-intentioned, inadvertently stifles the very innovation it seeks to encourage."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('reading', '{"text": "What began as a modest pilot program has since evolved into a cornerstone of the organization''s long-term strategy."}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('reading', '{"text": "The findings, though preliminary, challenge several assumptions that have long underpinned conventional wisdom in the field."}', 0.68, 'C1', 'approved', 'manual', 'education', 'practice', :'s1_id', 4),
('reading', '{"text": "Negotiations stalled indefinitely once it became apparent that neither side was prepared to make meaningful concessions."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('reading', '{"text": "The firm''s reputation, once unassailable, has been gradually eroded by a series of ill-judged public statements."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('reading', '{"text": "Although the proposal garnered considerable enthusiasm initially, enthusiasm alone proved insufficient to secure its funding."}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('reading', '{"text": "The policy''s unintended consequences have prompted a reassessment of its underlying assumptions by its original architects."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('reading', '{"text": "Few anticipated that the merger, once finalized, would precipitate such a profound shift in market dynamics."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('reading', '{"text": "The study''s methodology has drawn scrutiny from peers who question whether its sample adequately represents the population."}', 0.74, 'C1', 'approved', 'manual', 'education', 'practice', :'s2_id', 5),
('reading', '{"text": "The board''s decision to proceed despite mounting objections has been characterized by some as reckless and by others as decisive."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('reading', '{"text": "Investors remain divided over whether the company''s aggressive expansion reflects genuine confidence or an attempt to mask underlying weaknesses."}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('reading', '{"text": "The report''s conclusions, while compelling, rest on assumptions that subsequent analysts have been reluctant to accept uncritically."}', 0.78, 'C1', 'approved', 'manual', 'education', 'practice', :'s3_id', 3),
('reading', '{"text": "What distinguishes this proposal from its predecessors is its willingness to confront, rather than circumvent, the underlying structural issues."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('reading', '{"text": "The dispute, having simmered for years, finally erupted into open conflict once the terms of the contract were disclosed publicly."}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
INSERT INTO units (item_type_id, name, order_index) VALUES ('reading_selective', 'C1 - Advanced', 5) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
