INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('reading_selective', '{"text": "The clause stipulates that liability is capped at the contract value unless gross negligence can be demonstrated.", "question": "Under what condition does liability exceed the cap?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["gross negligence", "if gross negligence is shown"]}', :'s1_id', 1),
('reading_selective', '{"text": "The amendment was shelved indefinitely after lobbyists successfully argued it would disproportionately burden smaller firms.", "question": "Why was the amendment shelved?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["it would burden smaller firms", "disproportionate burden on small firms"]}', :'s1_id', 2),
('reading_selective', '{"text": "The audit revealed that discrepancies, though minor individually, collectively amounted to a significant shortfall.", "question": "What did the discrepancies amount to collectively?"}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["a significant shortfall", "a large shortfall"]}', :'s1_id', 3),
('reading_selective', '{"text": "The embargo will remain in effect until both parties ratify the revised terms of engagement.", "question": "What must happen for the embargo to end?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["both parties must ratify the terms", "ratification by both parties"]}', :'s1_id', 4),
('reading_selective', '{"text": "The panel''s ruling, though not legally binding, is expected to carry significant weight in future proceedings.", "question": "Is the ruling legally binding?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "not legally binding"]}', :'s1_id', 5),
('reading_selective', '{"text": "The restructuring plan was abandoned once it became clear that projected savings had been substantially overstated.", "question": "Why was the restructuring plan abandoned?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["savings were overstated", "the projected savings were inflated"]}', :'s2_id', 1),
('reading_selective', '{"text": "The firm''s valuation hinges largely on assumptions about future growth that many analysts consider overly optimistic.", "question": "What do analysts consider overly optimistic?"}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["growth assumptions", "the growth projections"]}', :'s2_id', 2),
('reading_selective', '{"text": "The arbitration process was expedited after both parties agreed to waive their right to a formal hearing.", "question": "What did both parties waive?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["their right to a formal hearing", "a formal hearing"]}', :'s2_id', 3),
('reading_selective', '{"text": "The policy''s critics argue that its exemptions effectively undermine its stated purpose.", "question": "What do critics argue the exemptions do?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["undermine the policy''s purpose", "weaken its purpose"]}', :'s2_id', 4),
('reading_selective', '{"text": "The committee deferred judgment pending further evidence, despite pressure to issue an immediate ruling.", "question": "What did the committee do despite pressure?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["deferred judgment", "delayed its ruling"]}', :'s2_id', 5),
('reading_selective', '{"text": "The clause''s ambiguity has given rise to conflicting interpretations among legal scholars.", "question": "What has the clause''s ambiguity given rise to?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["conflicting interpretations", "disagreement among scholars"]}', :'s3_id', 1),
('reading_selective', '{"text": "The board''s tacit approval of the plan was interpreted by staff as an implicit endorsement of further cuts.", "question": "How did staff interpret the board''s tacit approval?"}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["as endorsement of further cuts", "an implicit endorsement"]}', :'s3_id', 2),
('reading_selective', '{"text": "The settlement precludes either party from disclosing its terms to third parties.", "question": "What does the settlement preclude?"}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["disclosing its terms", "revealing the terms"]}', :'s3_id', 3),
('reading_selective', '{"text": "The resolution was adopted unanimously, notwithstanding reservations expressed by several delegates beforehand.", "question": "Did any delegates express reservations?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["yes", "several did"]}', :'s3_id', 4),
('reading_selective', '{"text": "The firm''s insistence on confidentiality clauses has drawn criticism from former employees alleging a culture of silence.", "question": "What have former employees alleged?"}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["a culture of silence", "a culture of secrecy"]}', :'s3_id', 5);
