INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('short_answer', '{"question": "Why might shareholders challenge a board''s decision even when it is legally sound?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('short_answer', '{"question": "What distinguishes a genuine conflict of interest from a mere perception of one?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('short_answer', '{"question": "Why do regulators sometimes favor incremental reform over sweeping legislative change?"}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('short_answer', '{"question": "What risks does a company face by prioritizing short-term gains over long-term sustainability?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('short_answer', '{"question": "Why can excessive transparency sometimes undermine organizational trust rather than build it?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('short_answer', '{"question": "What explains the persistence of groupthink even in highly experienced teams?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('short_answer', '{"question": "Why might a company deliberately understate its own projected growth?"}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('short_answer', '{"question": "What are the limitations of relying solely on quantitative data for strategic decisions?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('short_answer', '{"question": "Why do mergers between culturally incompatible organizations often underperform expectations?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('short_answer', '{"question": "What justifies the use of non-disclosure agreements in competitive industries?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('short_answer', '{"question": "Why might regulatory bodies be reluctant to intervene even amid clear market failures?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('short_answer', '{"question": "What are the ethical implications of using predictive algorithms in hiring decisions?"}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('short_answer', '{"question": "Why does organizational culture often prove more difficult to change than formal policy?"}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('short_answer', '{"question": "What distinguishes calculated risk-taking from reckless decision-making in leadership?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('short_answer', '{"question": "Why might an organization resist disclosing an internal failure even when transparency would ultimately serve its interests?"}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
