INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('conversations', '{"dialogue": "A: The regulator is threatening sanctions. B: On what grounds? A: Alleged non-compliance with disclosure requirements.", "question": "What is the alleged basis for sanctions?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["non-compliance with disclosure requirements", "disclosure violations"]}', :'s1_id', 1),
('conversations', '{"dialogue": "A: The board overruled the CEO. B: On the acquisition? A: Yes, citing excessive risk exposure.", "question": "Why did the board overrule the CEO?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["excessive risk exposure", "too much risk"]}', :'s1_id', 2),
('conversations', '{"dialogue": "A: The settlement terms leaked. B: How damaging is that? A: Potentially, given the confidentiality clause.", "question": "Why is the leak potentially damaging?"}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["there was a confidentiality clause", "breach of confidentiality"]}', :'s1_id', 3),
('conversations', '{"dialogue": "A: The audit flagged a conflict of interest. B: Involving whom? A: A senior director with undisclosed holdings.", "question": "Who was involved in the conflict of interest?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["a senior director", "the director with undisclosed holdings"]}', :'s1_id', 4),
('conversations', '{"dialogue": "A: The merger talks resumed. B: After the breakdown? A: Yes, under new leadership on both sides.", "question": "Under what circumstances did talks resume?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["under new leadership", "with new leadership on both sides"]}', :'s1_id', 5),
('conversations', '{"dialogue": "A: Shareholders are demanding accountability. B: For what specifically? A: The undisclosed losses from last quarter.", "question": "What are shareholders demanding accountability for?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["undisclosed losses", "the hidden losses"]}', :'s2_id', 1),
('conversations', '{"dialogue": "A: The whistleblower came forward. B: What did they allege? A: Systematic falsification of safety records.", "question": "What did the whistleblower allege?"}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["falsification of safety records", "falsified safety records"]}', :'s2_id', 2),
('conversations', '{"dialogue": "A: The tribunal issued its verdict. B: In whose favor? A: The plaintiff, though damages were reduced.", "question": "In whose favor did the tribunal rule?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["the plaintiff"]}', :'s2_id', 3),
('conversations', '{"dialogue": "A: The firm is restructuring its debt. B: Voluntarily? A: Not entirely, under pressure from creditors.", "question": "Is the restructuring entirely voluntary?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "not entirely"]}', :'s2_id', 4),
('conversations', '{"dialogue": "A: The CEO resigned abruptly. B: Any explanation given? A: Only vague references to personal reasons.", "question": "What explanation was given for the resignation?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["personal reasons", "vague personal reasons"]}', :'s2_id', 5),
('conversations', '{"dialogue": "A: The commission''s findings were damning. B: Will there be consequences? A: Likely, though enforcement remains uncertain.", "question": "Is enforcement of consequences certain?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "uncertain"]}', :'s3_id', 1),
('conversations', '{"dialogue": "A: The acquisition was blocked. B: By regulators? A: Yes, over monopoly concerns.", "question": "Why was the acquisition blocked?"}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["monopoly concerns", "antitrust concerns"]}', :'s3_id', 2),
('conversations', '{"dialogue": "A: The company''s defense rested on a technicality. B: Which one? A: A procedural flaw in how evidence was gathered.", "question": "What was the technicality?"}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["a procedural flaw", "how evidence was gathered"]}', :'s3_id', 3),
('conversations', '{"dialogue": "A: The investigation was quietly dropped. B: Why? A: Insufficient evidence, according to the official statement.", "question": "Why was the investigation dropped?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["insufficient evidence", "lack of evidence"]}', :'s3_id', 4),
('conversations', '{"dialogue": "A: The settlement was far larger than expected. B: Any public reaction? A: Mostly outrage over the lack of accountability.", "question": "What was the public reaction?"}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["outrage", "outrage over lack of accountability"]}', :'s3_id', 5);
