INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('dictation', '{"text": "The regulator imposed sanctions despite the firm''s repeated assurances."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('dictation', '{"text": "The board overruled the CEO, citing excessive risk exposure."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('dictation', '{"text": "The settlement terms leaked despite a strict confidentiality clause."}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('dictation', '{"text": "The audit flagged an undisclosed conflict of interest involving a director."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('dictation', '{"text": "Merger talks resumed only after leadership changed on both sides."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('dictation', '{"text": "Shareholders demanded accountability for the undisclosed quarterly losses."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('dictation', '{"text": "The whistleblower alleged systematic falsification of safety records."}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('dictation', '{"text": "The tribunal ruled in the plaintiff''s favor, though damages were reduced."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('dictation', '{"text": "The firm is restructuring its debt under pressure from creditors."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('dictation', '{"text": "The CEO resigned abruptly, citing only vague personal reasons."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('dictation', '{"text": "The commission''s findings were damning, though enforcement remains uncertain."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('dictation', '{"text": "Regulators blocked the acquisition over concerns about monopoly power."}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('dictation', '{"text": "The company''s defense rested on a procedural flaw in the evidence."}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('dictation', '{"text": "The investigation was quietly dropped, citing insufficient evidence."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('dictation', '{"text": "Public outrage followed once the settlement amount was disclosed."}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
