INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('passage_reconstruction', '{"passage": "Regulators fined the bank after an investigation revealed that risk disclosures had been systematically understated for years, misleading both investors and oversight bodies."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["regulators fined the bank", "risk disclosures were understated for years", "investors and oversight bodies were misled"]}', :'s1_id', 1),
('passage_reconstruction', '{"passage": "The merger, once hailed as transformative, has since been quietly unwound after integration costs far exceeded initial projections, eroding much of the anticipated value."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the merger was hailed as transformative", "it was quietly unwound", "integration costs exceeded projections"]}', :'s1_id', 2),
('passage_reconstruction', '{"passage": "A whistleblower''s testimony prompted a formal inquiry into the agency''s procurement practices, revealing a pattern of favoritism toward a handful of politically connected contractors."}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["a whistleblower prompted an inquiry", "the inquiry looked at procurement practices", "it revealed favoritism toward connected contractors"]}', :'s1_id', 3),
('passage_reconstruction', '{"passage": "Despite assurances of transparency, the company''s decision to withhold the full audit from shareholders drew sharp criticism and renewed calls for governance reform."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the company withheld the full audit", "this drew sharp criticism", "it renewed calls for governance reform"]}', :'s1_id', 4),
('passage_reconstruction', '{"passage": "The court''s ruling, while narrow in scope, has been widely interpreted as a rebuke of the agency''s broader enforcement strategy."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the ruling was narrow in scope", "it was interpreted as a rebuke", "it concerned the agency''s enforcement strategy"]}', :'s1_id', 5),
('passage_reconstruction', '{"passage": "After years of resisting reform, the industry finally conceded to stricter oversight once a string of high-profile failures made the status quo untenable."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the industry resisted reform for years", "it conceded to stricter oversight", "high-profile failures made the status quo untenable"]}', :'s2_id', 1),
('passage_reconstruction', '{"passage": "The think tank''s report, though methodologically sound, was dismissed by critics who questioned the motives of its primary funders."}', 0.73, 'C1', 'approved', 'manual', 'education', 'practice', '{"key_points": ["the report was methodologically sound", "it was dismissed by critics", "critics questioned the funders'' motives"]}', :'s2_id', 2),
('passage_reconstruction', '{"passage": "The company''s stock plunged after an analyst revealed that reported revenues had been inflated through a series of undisclosed related-party transactions."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["stock plunged after an analyst''s report", "revenues were inflated", "this was done through undisclosed related-party transactions"]}', :'s2_id', 3),
('passage_reconstruction', '{"passage": "Although the settlement avoided a lengthy trial, critics argued it allowed the company to escape meaningful accountability for its conduct."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the settlement avoided a lengthy trial", "critics said it let the company escape accountability"]}', :'s2_id', 4),
('passage_reconstruction', '{"passage": "The agency''s sudden reversal on the policy, after years of defending it publicly, left many observers questioning what internal pressures had prompted the change."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the agency reversed its policy suddenly", "it had defended the policy for years", "observers questioned what pressures caused the change"]}', :'s2_id', 5),
('passage_reconstruction', '{"passage": "The inquiry concluded that systemic failures, rather than any single individual''s negligence, were ultimately responsible for the disaster."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the inquiry blamed systemic failures", "not any single individual''s negligence", "these failures caused the disaster"]}', :'s3_id', 1),
('passage_reconstruction', '{"passage": "The firm''s attempt to rebrand following the scandal was widely seen as superficial, failing to address the structural issues that had precipitated the crisis."}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the firm tried to rebrand after the scandal", "this was seen as superficial", "it failed to address the structural issues"]}', :'s3_id', 2),
('passage_reconstruction', '{"passage": "The legislation, drafted hastily in response to public outcry, has since been criticized for creating loopholes nearly as problematic as the practices it sought to eliminate."}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the legislation was drafted hastily", "it responded to public outcry", "it created new loopholes nearly as problematic"]}', :'s3_id', 3),
('passage_reconstruction', '{"passage": "The acquisition, pursued aggressively despite internal warnings, ultimately proved to be the catalyst for the company''s most severe financial crisis in a decade."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the acquisition was pursued despite warnings", "it became the catalyst for a financial crisis", "it was the worst crisis in a decade"]}', :'s3_id', 4),
('passage_reconstruction', '{"passage": "The commission''s recommendations, though well-received in principle, have languished for want of political will to implement them."}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["the recommendations were well-received in principle", "they have languished", "there is a lack of political will to implement them"]}', :'s3_id', 5);
