INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('reading_comprehension', '{"passage": "Legal Brief: The appellant argues the lower court erred by excluding key testimony, while the respondent maintains the exclusion was procedurally justified.", "question": "What does the appellant argue?", "options": ["The exclusion was justified", "The lower court erred", "No testimony was excluded", "The respondent is correct"]}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 1),
('reading_comprehension', '{"passage": "Analyst Note: While headline revenue grew, margin compression driven by input costs raises concerns about underlying profitability.", "question": "What raises concerns about profitability?", "options": ["Revenue growth", "Margin compression", "Input cost reduction", "Nothing"]}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 2),
('reading_comprehension', '{"passage": "Policy Brief: Proponents argue the measure will reduce emissions; opponents counter that enforcement mechanisms remain inadequately defined.", "question": "What do opponents counter?", "options": ["Emissions will not be reduced", "Enforcement is poorly defined", "The measure is too strict", "There is no opposition"]}', 0.70, 'C1', 'approved', 'manual', 'environment', 'practice', '{"correctIndex": 1}', :'s1_id', 3),
('reading_comprehension', '{"passage": "Internal Memo: Despite assurances to the contrary, the restructuring will result in the elimination of roughly 200 positions across three departments.", "question": "How many positions will be eliminated?", "options": ["None", "Roughly 200", "Three", "All positions"]}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s1_id', 4),
('reading_comprehension', '{"passage": "Research Abstract: The study''s conclusions, while statistically significant, may not generalize beyond the narrow demographic sampled.", "question": "What limits the conclusions'' generalizability?", "options": ["Lack of statistical significance", "The narrow demographic sampled", "Too large a sample", "Nothing limits it"]}', 0.69, 'C1', 'approved', 'manual', 'education', 'practice', '{"correctIndex": 1}', :'s1_id', 5),
('reading_comprehension', '{"passage": "Board Minutes: The motion to approve the acquisition passed by a narrow margin, with three directors abstaining over unresolved due-diligence concerns.", "question": "Why did three directors abstain?", "options": ["They opposed the acquisition", "Unresolved due-diligence concerns", "They were absent", "No reason given"]}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 1),
('reading_comprehension', '{"passage": "Court Filing: The defense contends the contract''s ambiguous language should be interpreted in the defendant''s favor under established precedent.", "question": "What does the defense contend?", "options": ["The contract is unambiguous", "Ambiguity should favor the defendant", "There is no precedent", "The plaintiff should win"]}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 2),
('reading_comprehension', '{"passage": "Financial Disclosure: Although the company reported a net loss, adjusted figures exclude a one-time charge related to the divested subsidiary.", "question": "What do adjusted figures exclude?", "options": ["Normal operating costs", "A one-time charge", "All revenue", "Nothing"]}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 3),
('reading_comprehension', '{"passage": "Committee Report: While the pilot program showed promise, scaling it nationally would require funding levels the current budget cannot accommodate.", "question": "What would scaling the program require?", "options": ["Less funding", "Funding beyond the current budget", "No additional funding", "A smaller pilot"]}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 4),
('reading_comprehension', '{"passage": "Arbitration Summary: The tribunal found in favor of the claimant on liability but reduced damages substantially due to contributory negligence.", "question": "Why were damages reduced?", "options": ["The claimant lost on liability", "Contributory negligence", "No damages were awarded", "The tribunal made an error"]}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s2_id', 5),
('reading_comprehension', '{"passage": "Regulatory Notice: The exemption applies only to firms with revenues below a specified threshold, a detail critics say disproportionately favors large incumbents.", "question": "What do critics say the exemption does?", "options": ["Favors small firms fairly", "Disproportionately favors large incumbents", "Applies to everyone equally", "Has no effect"]}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 1),
('reading_comprehension', '{"passage": "Audit Summary: The discrepancies, though individually immaterial, collectively suggest a pattern of inadequate internal controls.", "question": "What do the discrepancies collectively suggest?", "options": ["Strong internal controls", "A pattern of inadequate controls", "No real issue", "Deliberate fraud only"]}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 2),
('reading_comprehension', '{"passage": "Appellate Opinion: The majority held that the lower court''s interpretation was overly broad, while the dissent argued it was entirely consistent with precedent.", "question": "What did the majority hold?", "options": ["The interpretation was too narrow", "The interpretation was overly broad", "There was no interpretation issue", "The dissent was correct"]}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 3),
('reading_comprehension', '{"passage": "Economic Outlook: Forecasters caution that while headline indicators appear positive, underlying structural weaknesses could undermine medium-term growth.", "question": "What could undermine medium-term growth?", "options": ["Positive headline indicators", "Underlying structural weaknesses", "Strong forecasting", "Nothing"]}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 4),
('reading_comprehension', '{"passage": "Compliance Review: The review found that while no laws were technically broken, the firm''s practices fell well short of industry best practice.", "question": "What did the review conclude about the firm''s practices?", "options": ["They broke the law", "They fell short of best practice", "They exceeded best practice", "No conclusion was reached"]}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 1}', :'s3_id', 5);
