('response_selection', '{"text": "Regulators have requested additional documentation on our pricing model.", "options": ["We should compile everything they need promptly.", "He enjoys watching documentaries.", "The lobby was recently repainted."]}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 1),
('response_selection', '{"text": "A key supplier has filed for bankruptcy protection.", "options": ["We need contingency plans for our supply chain.", "The vending machine is out of order.", "She prefers tea to coffee."]}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 2),
