('response_selection', '{"text": "An internal investigation uncovered falsified expense reports.", "options": ["We need to involve HR and legal immediately.", "The office recently got new furniture.", "She likes gardening on weekends."]}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', '{"correctIndex": 0}', :'s3_id', 4),
