('passage_comprehension', '{"story": "A pharmaceutical company faced a lawsuit after a drug''s side effects were allegedly understated in clinical trial reports. The company settled out of court to avoid prolonged litigation, without admitting wrongdoing.", "question": "Why did the company settle?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["to avoid prolonged litigation", "avoid a long court case"]}', :'s1_id', 1),
('passage_comprehension', '{"story": "A pharmaceutical company faced a lawsuit after a drug''s side effects were allegedly understated in clinical trial reports. The company settled out of court to avoid prolonged litigation, without admitting wrongdoing.", "question": "Did the company admit wrongdoing?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["no", "they did not admit it"]}', :'s1_id', 2),
('passage_comprehension', '{"story": "A pharmaceutical company faced a lawsuit after a drug''s side effects were allegedly understated in clinical trial reports. The company settled out of court to avoid prolonged litigation, without admitting wrongdoing.", "question": "What was allegedly understated?"}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["the drug''s side effects", "side effects in trial reports"]}', :'s1_id', 3),
