('passage_comprehension', '{"story": "A city''s transit authority faced criticism after an independent review found that ridership projections used to justify a costly expansion had been significantly overstated, raising questions about the project''s original approval.", "question": "What did the review find?"}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"acceptable_answers": ["ridership projections were overstated", "projections were inflated"]}', :'s2_id', 1),
