('passage_comprehension', '{"story": "A technology firm''s stock dropped sharply after a former employee alleged in a lawsuit that the company had misrepresented its user growth figures to investors ahead of its public offering.", "question": "What did the former employee allege?"}', 0.74, 'C1', 'approved', 'manual', 'technology', 'practice', '{"acceptable_answers": ["misrepresented user growth figures", "inflated growth numbers"]}', :'s2_id', 3),
('passage_comprehension', '{"story": "A technology firm''s stock dropped sharply after a former employee alleged in a lawsuit that the company had misrepresented its user growth figures to investors ahead of its public offering.", "question": "When did this alleged misrepresentation happen?"}', 0.72, 'C1', 'approved', 'manual', 'technology', 'practice', '{"acceptable_answers": ["ahead of its public offering", "before the IPO"]}', :'s2_id', 4),
('passage_comprehension', '{"story": "An energy company was fined after regulators determined that emissions data submitted over several years had been calculated using an outdated and overly favorable methodology.", "question": "Why was the energy company fined?"}', 0.74, 'C1', 'approved', 'manual', 'environment', 'practice', '{"acceptable_answers": ["emissions data used an outdated methodology", "they miscalculated emissions"]}', :'s2_id', 5),
