INSERT INTO units (item_type_id, name, order_index) VALUES ('story_retelling', 'C1 - Advanced', 5) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('story_retelling', '{"story": "A mid-sized manufacturer discovered that a long-trusted supplier had been quietly substituting cheaper materials without disclosure. Rather than pursuing immediate legal action, the company renegotiated the contract with strict new quality clauses, preserving the relationship while protecting its interests."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('story_retelling', '{"story": "An established law firm lost several junior associates to a rival offering more flexible hours. Rather than matching the offer outright, the partners redesigned the firm''s entire career track to emphasize autonomy, which ultimately reduced turnover across the board."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('story_retelling', '{"story": "A city''s water utility faced mounting public anger after a contamination scare, even though testing later showed the risk had been minimal. Officials acknowledged that poor communication, more than the incident itself, had driven the backlash, and overhauled their crisis messaging accordingly."}', 0.70, 'C1', 'approved', 'manual', 'community', 'practice', :'s1_id', 3),
('story_retelling', '{"story": "A university''s endowment suffered losses after an overly aggressive investment strategy backfired during a market downturn. The board replaced its investment committee and adopted a far more conservative approach, prioritizing long-term stability over short-term returns."}', 0.68, 'C1', 'approved', 'manual', 'education', 'practice', :'s1_id', 4),
('story_retelling', '{"story": "A regional airline struggled for years with a reputation for poor customer service. A new CEO empowered frontline staff to resolve complaints on the spot without managerial approval, and customer satisfaction scores improved dramatically within a single year."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('story_retelling', '{"story": "A pharmaceutical firm faced intense pressure to rush a promising drug to market. Despite the financial incentive, the research team insisted on completing an additional trial phase, which ultimately uncovered a rare but serious side effect before the drug reached patients."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('story_retelling', '{"story": "A family-owned business resisted modernizing for decades, relying on loyal customers and tradition. When a younger generation took over, they introduced digital ordering cautiously, preserving the brand''s identity while finally reversing years of declining revenue."}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('story_retelling', '{"story": "A nonprofit organization discovered that a major donor''s funds had strings attached that conflicted with its mission. After considerable internal debate, the board declined the donation, a decision that initially strained finances but ultimately reinforced the organization''s credibility."}', 0.74, 'C1', 'approved', 'manual', 'community', 'practice', :'s2_id', 3),
('story_retelling', '{"story": "A manufacturing plant experienced a near-miss safety incident that could have been catastrophic. Rather than quietly addressing it internally, management disclosed the incident publicly and invited external auditors, a move that was initially unpopular but ultimately rebuilt worker trust."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 4),
('story_retelling', '{"story": "A software company''s flagship product was overtaken by a nimbler competitor within a single product cycle. Instead of competing directly, leadership chose to pivot toward an underserved enterprise niche, a decision that initially alarmed investors but eventually proved more profitable."}', 0.74, 'C1', 'approved', 'manual', 'technology', 'practice', :'s2_id', 5),
('story_retelling', '{"story": "A government agency''s decades-old procurement process had long been criticized as needlessly slow. A newly appointed director overhauled the system entirely, facing fierce resistance from entrenched staff, but ultimately cut average procurement times by more than half."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('story_retelling', '{"story": "A mining company faced sustained protests over its environmental record despite being in full legal compliance. Rather than dismissing the criticism, executives voluntarily adopted stricter standards than required, which gradually repaired the company''s public image over several years."}', 0.77, 'C1', 'approved', 'manual', 'environment', 'practice', :'s3_id', 2),
('story_retelling', '{"story": "A hospital system discovered that a significant proportion of readmissions stemmed from inadequate post-discharge instructions rather than clinical failures. Addressing this required no new technology, only a redesigned discharge process, yet it reduced readmissions more than any prior clinical intervention had."}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('story_retelling', '{"story": "A long-running family dispute over a company''s succession nearly led to its dissolution. An external mediator proposed splitting leadership roles along functional rather than hereditary lines, a compromise that satisfied no one entirely but preserved the business for another generation."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('story_retelling', '{"story": "A financial institution''s risk models had consistently underestimated the likelihood of a severe downturn, a flaw that only became apparent once the downturn actually occurred. The subsequent overhaul of its modeling assumptions became an industry case study in the limits of historical data."}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
