('open_questions', '{"prompt": "To what extent should companies be held accountable for the actions of their suppliers?"}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('open_questions', '{"prompt": "Is it ever justifiable for a company to prioritize shareholder interests over employee wellbeing?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('open_questions', '{"prompt": "How should societies balance innovation with the risks posed by unregulated emerging technologies?"}', 0.70, 'C1', 'approved', 'manual', 'technology', 'practice', :'s1_id', 3),
('open_questions', '{"prompt": "What obligations, if any, do successful individuals have toward the communities that helped shape them?"}', 0.68, 'C1', 'approved', 'manual', 'general', 'practice', :'s1_id', 4),
('open_questions', '{"prompt": "Can transparency alone restore trust in an institution that has lost public confidence?"}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('open_questions', '{"prompt": "Is economic growth an adequate measure of a society''s overall progress?"}', 0.72, 'C1', 'approved', 'manual', 'general', 'practice', :'s2_id', 1),
('open_questions', '{"prompt": "How should organizations weigh short-term financial pressure against long-term ethical considerations?"}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('open_questions', '{"prompt": "To what degree should individuals be responsible for verifying the information they share publicly?"}', 0.74, 'C1', 'approved', 'manual', 'culture', 'practice', :'s2_id', 3),
('open_questions', '{"prompt": "Does the pursuit of efficiency ever come at too great a cost to human judgment?"}', 0.72, 'C1', 'approved', 'manual', 'technology', 'practice', :'s2_id', 4),
('open_questions', '{"prompt": "What distinguishes legitimate dissent within an organization from disruptive insubordination?"}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('open_questions', '{"prompt": "Should historical injustices influence present-day corporate or governmental policy?"}', 0.76, 'C1', 'approved', 'manual', 'general', 'practice', :'s3_id', 1),
('open_questions', '{"prompt": "Is it possible to regulate artificial intelligence effectively without stifling its development?"}', 0.77, 'C1', 'approved', 'manual', 'technology', 'practice', :'s3_id', 2),
('open_questions', '{"prompt": "How should institutions respond when public opinion and expert consensus diverge sharply?"}', 0.78, 'C1', 'approved', 'manual', 'general', 'practice', :'s3_id', 3),
('open_questions', '{"prompt": "What role, if any, should sentiment play in decisions that are fundamentally economic in nature?"}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('open_questions', '{"prompt": "Can an organization genuinely reform its culture without a change in leadership?"}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
