INSERT INTO units (item_type_id, name, order_index) VALUES ('summary_and_opinion', 'C1 - Advanced', 5) RETURNING id \gset u_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 1', 1) RETURNING id \gset s1_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 2', 2) RETURNING id \gset s2_
INSERT INTO sets (unit_id, name, order_index) VALUES (:'u_id', 'Set 3', 3) RETURNING id \gset s3_
INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, answer_set, set_id, set_order) VALUES
('summary_and_opinion', '{"passage": "Several governments are debating whether to tax unrealized capital gains on large stock holdings. Proponents argue it would reduce wealth inequality, while opponents warn it could trigger capital flight and depress investment."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["governments debate taxing unrealized gains", "proponents cite reduced inequality", "opponents warn of capital flight"]}', :'s1_id', 1),
('summary_and_opinion', '{"passage": "A growing number of universities are reconsidering standardized testing requirements for admissions. Supporters of the change argue it broadens access, while critics worry it removes an objective benchmark for comparing applicants."}', 0.69, 'C1', 'approved', 'manual', 'education', 'practice', '{"key_points": ["universities reconsider testing requirements", "supporters cite broader access", "critics worry about losing an objective benchmark"]}', :'s1_id', 2),
('summary_and_opinion', '{"passage": "Some central banks are exploring digital currencies issued directly by the state. Advocates claim this would increase financial inclusion, while skeptics raise concerns about privacy and government overreach."}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["central banks explore digital currencies", "advocates cite financial inclusion", "skeptics raise privacy and overreach concerns"]}', :'s1_id', 3),
('summary_and_opinion', '{"passage": "A number of corporations are tying executive compensation to environmental and social metrics, not just financial performance. Supporters see this as overdue accountability, while critics call it a superficial gesture that obscures deeper issues."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["corporations tie pay to social/environmental metrics", "supporters see overdue accountability", "critics call it superficial"]}', :'s1_id', 4),
('summary_and_opinion', '{"passage": "Several nations are considering granting legal personhood to rivers and ecosystems to strengthen environmental protections. Proponents argue this creates stronger legal standing, while critics question how such rights could practically be enforced."}', 0.69, 'C1', 'approved', 'manual', 'environment', 'practice', '{"key_points": ["nations consider legal personhood for ecosystems", "proponents cite stronger legal standing", "critics question enforcement"]}', :'s1_id', 5),
('summary_and_opinion', '{"passage": "Some employers are experimenting with permanently eliminating performance reviews altogether, replacing them with continuous informal feedback. Supporters say this reduces anxiety and improves honesty, while skeptics worry it removes necessary structure and accountability."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["employers eliminate formal performance reviews", "supporters cite reduced anxiety", "skeptics worry about lost structure"]}', :'s2_id', 1),
('summary_and_opinion', '{"passage": "A debate has emerged over whether social media platforms should be legally liable for user-generated misinformation. Advocates of liability argue platforms profit from engagement regardless of harm, while opponents warn it would chill legitimate speech."}', 0.73, 'C1', 'approved', 'manual', 'technology', 'practice', '{"key_points": ["debate over platform liability for misinformation", "advocates cite profit from harmful engagement", "opponents warn of chilled speech"]}', :'s2_id', 2),
('summary_and_opinion', '{"passage": "Several countries are debating mandatory national service programs for young adults. Supporters argue it builds civic cohesion, while opponents view it as an infringement on individual liberty."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["debate over mandatory national service", "supporters cite civic cohesion", "opponents see it as infringing on liberty"]}', :'s2_id', 3),
('summary_and_opinion', '{"passage": "A growing number of companies are adopting four-day work weeks permanently rather than as a trial. Supporters cite sustained productivity gains, while skeptics argue early results may not hold across all industries long-term."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["companies adopt permanent four-day weeks", "supporters cite sustained productivity", "skeptics doubt long-term results across industries"]}', :'s2_id', 4),
('summary_and_opinion', '{"passage": "Some policymakers propose taxing automation to fund retraining for displaced workers. Proponents say this eases the transition fairly, while opponents argue it could slow beneficial technological adoption overall."}', 0.74, 'C1', 'approved', 'manual', 'technology', 'practice', '{"key_points": ["policymakers propose an automation tax", "proponents say it eases worker transitions", "opponents fear slowed technology adoption"]}', :'s2_id', 5),
('summary_and_opinion', '{"passage": "A controversial proposal would require corporations above a certain size to include worker representatives on their boards. Supporters argue this improves decision-making and accountability, while opponents contend it could slow governance and deter investment."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["proposal for worker board representation", "supporters cite better decisions and accountability", "opponents fear slower governance and less investment"]}', :'s3_id', 1),
('summary_and_opinion', '{"passage": "Some scientists argue that geoengineering, deliberately altering the climate to counteract warming, should be seriously researched as a last resort. Critics counter that it is far too risky and could discourage genuine emissions reduction."}', 0.77, 'C1', 'approved', 'manual', 'environment', 'practice', '{"key_points": ["scientists propose researching geoengineering", "it is framed as a last resort", "critics say it is risky and could discourage emissions cuts"]}', :'s3_id', 2),
('summary_and_opinion', '{"passage": "A debate has intensified over whether universities should divest entirely from fossil fuel companies in their endowments. Advocates argue it aligns investments with institutional values, while opponents claim it sacrifices financial returns needed for other priorities."}', 0.78, 'C1', 'approved', 'manual', 'education', 'practice', '{"key_points": ["debate over university fossil fuel divestment", "advocates cite aligning values with investment", "opponents cite sacrificed financial returns"]}', :'s3_id', 3),
('summary_and_opinion', '{"passage": "Some legal scholars argue that corporations found guilty of repeated serious violations should face the equivalent of a corporate death penalty, forced dissolution, rather than fines alone. Critics warn this would be disproportionate and harm innocent employees."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', '{"key_points": ["scholars propose forced dissolution for repeat offenders", "an alternative to fines alone", "critics warn it would harm innocent employees"]}', :'s3_id', 4),
('summary_and_opinion', '{"passage": "A growing debate concerns whether algorithmic pricing, where companies use AI to set prices dynamically based on individual data, constitutes unfair discrimination. Supporters call it efficient market pricing, while critics argue it exploits information asymmetries against consumers."}', 0.79, 'C1', 'approved', 'manual', 'technology', 'practice', '{"key_points": ["debate over algorithmic, individualized pricing", "supporters call it efficient pricing", "critics say it exploits information asymmetries"]}', :'s3_id', 5);
