INSERT INTO items (item_type_id, content, difficulty, cefr_level, status, pipeline_version, topic, pool, set_id, set_order) VALUES
('typing', '{"text": "The regulator''s decision to impose sanctions, though legally sound, has nonetheless provoked considerable debate over its broader economic implications."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 1),
('typing', '{"text": "Critics of the ruling argue that it sets a precedent likely to be exploited by future litigants in similarly ambiguous circumstances."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 2),
('typing', '{"text": "The board''s tacit approval of the restructuring plan was widely interpreted as an implicit endorsement of further cost reductions."}', 0.70, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 3),
('typing', '{"text": "Although the settlement avoided protracted litigation, many observers questioned whether it afforded meaningful accountability."}', 0.68, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 4),
('typing', '{"text": "The firm''s reluctance to disclose the full extent of its losses has only intensified scrutiny from regulators and shareholders alike."}', 0.69, 'C1', 'approved', 'manual', 'business', 'practice', :'s1_id', 5),
('typing', '{"text": "Analysts remain divided over whether the company''s aggressive expansion reflects genuine strategic confidence or an attempt to obscure underlying vulnerabilities."}', 0.72, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 1),
('typing', '{"text": "The inquiry concluded that systemic shortcomings, rather than any single individual''s negligence, were ultimately responsible for the failure."}', 0.73, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 2),
('typing', '{"text": "Despite considerable internal resistance, the newly appointed director pressed ahead with reforms that many considered long overdue."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 3),
('typing', '{"text": "The committee''s findings, while methodologically rigorous, have nonetheless been contested by stakeholders with vested interests in the outcome."}', 0.72, 'C1', 'approved', 'manual', 'education', 'practice', :'s2_id', 4),
('typing', '{"text": "What distinguishes this proposal from its predecessors is its willingness to confront structural issues rather than merely circumvent them."}', 0.74, 'C1', 'approved', 'manual', 'business', 'practice', :'s2_id', 5),
('typing', '{"text": "The dispute, having simmered unresolved for years, finally erupted once the contested terms were disclosed to the public."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 1),
('typing', '{"text": "Shareholders have grown increasingly skeptical of management''s assurances, particularly given the pattern of understated risk disclosures."}', 0.77, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 2),
('typing', '{"text": "The policy''s critics contend that its exemptions effectively undermine the very objectives it was ostensibly designed to achieve."}', 0.78, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 3),
('typing', '{"text": "Few anticipated that the merger, once finalized, would precipitate such a profound and lasting shift in market dynamics."}', 0.76, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 4),
('typing', '{"text": "The board''s decision to proceed despite mounting objections has since been characterized, depending on one''s perspective, as either decisive or reckless."}', 0.79, 'C1', 'approved', 'manual', 'business', 'practice', :'s3_id', 5);
